import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'

/**
 * Example Unit Tests - Part 1
 *
 * This test suite covers 2 example files with comprehensive bidirectional testing:
 * 1. assign-subflow-primitive-arrays.now.ts - Subflow with primitive FlowArray outputs
 * 2. set-flow-variables-object-array-example.now.ts - Flow with complex FlowObject/FlowArray variables
 *
 * Each file has:
 * - Fluent → XML tests: Verify correct XML generation from TypeScript
 * - XML → Fluent tests: Verify correct TypeScript generation from XML
 */

describe('Example Unit Tests - Part 1', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // ============================================================================
    // TEST FILE 1: assign-subflow-primitive-arrays.now.ts
    // ============================================================================
    describe('File 1: assign-subflow-primitive-arrays - Fluent to XML', () => {
        test('Subflow definition with primitive FlowArray outputs', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-primitive-arrays.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify subflow record was created
            expect(merged['sys_hub_flow']).toBeDefined()
            const subflows = merged['sys_hub_flow']
            expect(subflows.length).toBeGreaterThanOrEqual(1)

            // Find the specific subflow we're testing
            const subflow = subflows.find((s: any) => s.name === 'Test Subflow - Primitive Arrays')
            expect(subflow).toBeDefined()
            expect(subflow.description).toBe('Subflow with primitive type FlowArray outputs')
            expect(subflow.type).toBe('subflow')

            // Verify outputs are defined
            expect(merged['sys_hub_flow_output']).toBeDefined()
            const outputs = merged['sys_hub_flow_output']

            // Should have 4 FlowArray outputs: stringList, numberList, booleanList, dateList
            expect(outputs.length).toBeGreaterThanOrEqual(4)

            // Verify stringList output with full details
            const stringList = outputs.find((o: any) => o.element === 'stringList')
            expect(stringList).toBeDefined()
            expect(stringList.label).toBe('String List')
            expect(stringList.mandatory).toBe(false)
            expect(stringList.active).toBe(true)

            // Verify numberList output with full details
            const numberList = outputs.find((o: any) => o.element === 'numberList')
            expect(numberList).toBeDefined()
            expect(numberList.label).toBe('Number List')
            expect(numberList.mandatory).toBe(false)
            expect(numberList.active).toBe(true)

            // Verify booleanList output with full details
            const booleanList = outputs.find((o: any) => o.element === 'booleanList')
            expect(booleanList).toBeDefined()
            expect(booleanList.label).toBe('Boolean List')
            expect(booleanList.mandatory).toBe(false)
            expect(booleanList.active).toBe(true)

            // Verify dateList output with full details
            const dateList = outputs.find((o: any) => o.element === 'dateList')
            expect(dateList).toBeDefined()
            expect(dateList.label).toBe('Date List')
            expect(dateList.mandatory).toBe(false)
            expect(dateList.active).toBe(true)
        })

        test('assignSubflowOutputs with primitive array values', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-primitive-arrays.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances for assignSubflowOutputs
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have multiple assignSubflowOutputs calls (11 tests)
            expect(flowLogicInstances.length).toBeGreaterThanOrEqual(11)

            // Test 1: String array with values
            const test1 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 1: String Array')
            expect(test1).toBeDefined()
            expect(test1.logic_definition).toBe('df4e1945c3e232002841b63b12d3ae3e') // assignSubflowOutputs sys_id

            const test1Values = unzipInputArray(test1.values) as any
            expect(test1Values.outputsToAssign).toBeDefined()
            expect(test1Values.outputsToAssign.length).toBeGreaterThan(0)

            // Verify stringList output assignment with value and displayValue
            const stringListOutput = test1Values.outputsToAssign.find((o: { name: string }) => o.name === 'stringList')
            expect(stringListOutput).toBeDefined()
            expect(stringListOutput.value).toBeDefined()
            expect(stringListOutput.displayValue).toBeDefined()
            // Verify it's an array value
            expect(stringListOutput.value).toContain('[')

            // Test 2: Integer array with values
            const test2 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 2: Integer Array')
            expect(test2).toBeDefined()

            // Test 3: Boolean array with values
            const test3 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 3: Boolean Array')
            expect(test3).toBeDefined()

            // Test 8: String array with datapills - comprehensive validation
            const test8 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 8: String Array with Datapills')
            expect(test8).toBeDefined()
            const test8Values = unzipInputArray(test8.values) as any
            const test8StringList = test8Values.outputsToAssign.find((o: any) => o.name === 'stringList')
            expect(test8StringList).toBeDefined()
            // Should contain datapill references in XML format {{...}}
            expect(test8StringList.value).toContain('{{')
            expect(test8StringList.value).toContain('}}')
            // Verify datapill structure includes field reference
            expect(test8StringList.value).toMatch(/\{\{[^}]+\}\}/)

            // Test 9: Integer array with datapills
            const test9 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 9: Integer Array with Datapills')
            expect(test9).toBeDefined()
            const test9Values = unzipInputArray(test9.values) as any
            const test9NumberList = test9Values.outputsToAssign.find((o: any) => o.name === 'numberList')
            expect(test9NumberList).toBeDefined()
            // Should contain datapill references
            expect(test9NumberList.value).toContain('{{')
            expect(test9NumberList.value).toContain('}}')

            // Test 10: Boolean array with datapills
            const test10 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 10: Boolean Array with Datapills')
            expect(test10).toBeDefined()
            const test10Values = unzipInputArray(test10.values) as any
            const test10BooleanList = test10Values.outputsToAssign.find((o: any) => o.name === 'booleanList')
            expect(test10BooleanList).toBeDefined()
            // Should contain datapill references
            expect(test10BooleanList.value).toContain('{{')
            expect(test10BooleanList.value).toContain('}}')
        })

        test('Inputs are correctly defined', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-primitive-arrays.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify inputs
            expect(merged['sys_hub_flow_input']).toBeDefined()
            const inputs = merged['sys_hub_flow_input']
            expect(inputs.length).toBe(4)

            // Verify inputString with type and mandatory flag
            const inputString = inputs.find((i: any) => i.element === 'inputString')
            expect(inputString).toBeDefined()
            expect(inputString.label).toBe('Input String')
            expect(inputString.internal_type).toBe('string')
            expect(inputString.mandatory).toBe(false)

            // Verify inputNumber with type and mandatory flag
            const inputNumber = inputs.find((i: any) => i.element === 'inputNumber')
            expect(inputNumber).toBeDefined()
            expect(inputNumber.label).toBe('Input Number')
            expect(inputNumber.internal_type).toBe('integer')
            expect(inputNumber.mandatory).toBe(false)

            // Verify inputBoolean with type and mandatory flag
            const inputBoolean = inputs.find((i: any) => i.element === 'inputBoolean')
            expect(inputBoolean).toBeDefined()
            expect(inputBoolean.label).toBe('Input Boolean')
            expect(inputBoolean.internal_type).toBe('boolean')
            expect(inputBoolean.mandatory).toBe(false)

            // Verify inputDate with type and mandatory flag
            const inputDate = inputs.find((i: any) => i.element === 'inputDate')
            expect(inputDate).toBeDefined()
            expect(inputDate.label).toBe('Input Date')
            expect(inputDate.internal_type).toBe('glide_date_time')
            expect(inputDate.mandatory).toBe(false)
        })

        test('Flow logic and action instances with validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'daily-data-processing-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances (setFlowVariables, if-else)
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify action instances (log actions)
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate the log action for daily processing start
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log daily processing start with assigned values'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            expect(logInputs('log_message')).toContain('Daily data processing started')
        })
    })

    describe('File 1: assign-subflow-primitive-arrays - XML to Fluent', () => {
        test('Subflow with primitive arrays transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.now.ts')

            const content = changedFiles[0].getContent()

            // Verify imports (combined in actual output)
            expect(content).toContain('import {')
            expect(content).toContain('Subflow')
            expect(content).toContain('FlowArray')
            expect(content).toContain('StringColumn')
            expect(content).toContain('IntegerColumn')
            expect(content).toContain('BooleanColumn')

            // Verify datapill transformations from XML to Fluent
            // XML format {{...}} should transform to wfa.dataPill(..., 'type')
            // Check for datapill with params.inputs reference
            expect(content).toMatch(/wfa\.dataPill\(.*params\.inputs\./)
            expect(content).toContain('DateTimeColumn')

            // Verify subflow definition
            expect(content).toContain('Subflow(')
            expect(content).toContain("name: 'Test Subflow - Primitive Arrays'")
            expect(content).toContain("description: 'Subflow with primitive type FlowArray outputs'")

            // Verify FlowArray outputs
            expect(content).toContain('stringList: FlowArray(')
            expect(content).toContain('numberList: FlowArray(')
            expect(content).toContain('booleanList: FlowArray(')
            expect(content).toContain('dateList: FlowArray(')

            // Verify elementType for arrays
            expect(content).toContain('elementType: StringColumn(')
            expect(content).toContain('elementType: IntegerColumn(')
            expect(content).toContain('elementType: BooleanColumn(')
            // DateTimeColumn may be named differently in XML transformation
            expect(content).toContain('dateList: FlowArray(')

            // Verify childName attributes
            expect(content).toContain("childName: 'stringItem'")
            expect(content).toContain("childName: 'numberItem'")

            // Verify assignSubflowOutputs calls
            expect(content).toContain('wfa.flowLogic.assignSubflowOutputs(')
            expect(content).toContain('_params.outputs')

            // Verify annotations are present
            expect(content).toContain('annotation:')
            expect(content).toContain('String Array')
            expect(content).toContain('Integer Array')
            expect(content).toContain('Boolean Array')
        })
    })

    // ============================================================================
    // TEST FILE 2: set-flow-variables-object-array-example.now.ts
    // ============================================================================
    describe('File 2: set-flow-variables-object-array-example - Fluent to XML', () => {
        test('Flow definition with complex FlowObject and FlowArray variables', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'set-flow-variables-object-array-example.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBe(1)

            const flow = flows[0]
            expect(flow.name).toBe('Comprehensive Test - FlowObject and FlowArray')
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBe('system')

            // Verify flow variables are defined
            expect(merged['sys_hub_flow_variable']).toBeDefined()
            const flowVars = merged['sys_hub_flow_variable']

            // Should have multiple complex flow variables
            expect(flowVars.length).toBeGreaterThan(5)
            const project = flowVars.find((v: any) => v.element === 'project')
            expect(project).toBeDefined()
        })

        test('setFlowVariables with FlowObject and FlowArray assignments', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'set-flow-variables-object-array-example.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances for setFlowVariables
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have 15 setFlowVariables test calls
            expect(flowLogicInstances.length).toBeGreaterThanOrEqual(15)

            // TEST 1: Happy Path - Object literals
            const test1 = flowLogicInstances.find(
                (fl: any) => fl.comment === 'TEST 1: Happy Path - Object literals assigned to FlowObject/FlowArray'
            )
            expect(test1).toBeDefined()
            expect(test1.logic_definition).toBe('4f787d1e0f9b0010ecf0cc52ff767ea0') // setFlowVariables sys_id

            const test1Values = unzipInputArray(test1.values) as any
            expect(test1Values.variables).toBeDefined()
            expect(test1Values.variables.length).toBeGreaterThan(0)

            // Verify userInfo variable assignment
            const userInfoVar = test1Values.variables.find((v: any) => v.name === 'userInfo')
            expect(userInfoVar).toBeDefined()

            // Verify tags variable assignment
            const tagsVar = test1Values.variables.find((v: any) => v.name === 'tags')
            expect(tagsVar).toBeDefined()

            // TEST 2: Datapills in FlowObject fields
            const test2 = flowLogicInstances.find(
                (fl: any) => fl.comment === 'TEST 2: Datapills used in FlowObject field values'
            )
            expect(test2).toBeDefined()
            const test2Values = unzipInputArray(test2.values) as any
            const test2UserInfo = test2Values.variables.find((v: any) => v.name === 'userInfo')
            expect(test2UserInfo).toBeDefined()
            // Should contain datapill references
            expect(test2UserInfo.value).toContain('{{')

            // TEST 3: Nested FlowObject
            const test3 = flowLogicInstances.find(
                (fl: any) => fl.comment === 'TEST 3: Nested FlowObject with literal values'
            )
            expect(test3).toBeDefined()
        })

        test('Flow record is correctly created', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'set-flow-variables-object-array-example.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record exists with correct properties
            const flows = merged['sys_hub_flow']
            const flow = flows.find((f: any) => f.name === 'Comprehensive Test - FlowObject and FlowArray')
            expect(flow).toBeDefined()
            expect(flow.run_as).toBe('system')
            expect(flow.description).toContain('Tests all possible cases')
        })
    })

    describe('File 2: set-flow-variables-object-array-example - XML to Fluent', () => {
        test('Flow with complex variables transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_57fff2c887d2496990087de5dd5d3888.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_57fff2c887d2496990087de5dd5d3888.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports (combined in actual output)
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('FlowObject')
            expect(content).toContain('FlowArray')
            expect(content).toContain('trigger')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Comprehensive Test - FlowObject and FlowArray'")
            expect(content).toContain('flowVariables: {')

            // Verify FlowObject variables
            expect(content).toContain('userInfo: FlowObject(')
            expect(content).toContain('fields: {')
            expect(content).toContain('name: StringColumn(')
            expect(content).toContain('email: StringColumn(')
            expect(content).toContain('age: IntegerColumn(')
            expect(content).toContain('isActive: BooleanColumn(')

            // Verify FlowArray variables
            expect(content).toContain('tags: FlowArray(')
            expect(content).toContain('elementType: FlowObject(')

            // Verify nested structures
            expect(content).toContain('config: FlowObject(')
            expect(content).toContain('settings: FlowObject(')
            expect(content).toContain('project: FlowObject(')
            expect(content).toContain('tasks: FlowArray(')

            // Verify trigger
            expect(content).toContain('trigger.record.created')
            expect(content).toContain('wfa.trigger(')

            // Verify setFlowVariables calls
            expect(content).toContain('wfa.flowLogic.setFlowVariables(')
            expect(content).toContain('_params.flowVariables')

            // Verify test annotations
            expect(content).toContain('TEST 1:')
            expect(content).toContain('TEST 2:')
            expect(content).toContain('TEST 3:')
        })
    })
})
